mapper.update:
UPDATE help_task
SET status = '已接单',
    helper_contact = #{helperContact},
    updated_time = #{updatedTime}
WHERE id = #{id}
  AND status = '待接单'

UPDATE help_task
SET status = '已完成',
    updated_time = #{updatedTime}
WHERE id = #{id}
  AND status = '已接单'

UPDATE help_task
SET status = '已取消',
    updated_time = #{updatedTime}
WHERE id = #{id}
  AND status IN ('待接单', '已接单')
